export function initGames(){const $=s=>document.querySelector(s);let mode='bubbles',running=false,score=0,deadline=0,interval=null,frame=null;let best=0;function readBest(){try{best=Number(localStorage.getItem('techbuzzs-best-'+mode)||0)}catch{best=0}$('#gameBest').textContent=best}function storeBest(){if(score>best){best=score;try{localStorage.setItem('techbuzzs-best-'+mode,String(best))}catch{}}$('#gameBest').textContent=best}function finish(message){running=false;clearInterval(interval);cancelAnimationFrame(frame);storeBest();$('#gameStart').textContent='Play again';$('#gameJump').hidden=mode!=='dino';$('#gameStatus').textContent=message+' Score: '+score+'. Best: '+best+'.';if(mode==='bubbles'){$('#bubbleArena').querySelectorAll('.bubble').forEach(b=>b.remove());$('#bubbleIdle').hidden=false;$('#bubbleIdle').innerHTML='<div><strong>A little pop of joy.</strong>Score '+score+' · ready for another round?</div>'}}function stop(){running=false;clearInterval(interval);cancelAnimationFrame(frame)}function updateScore(){$('#gameScore').textContent=score}function clock(){const left=Math.max(0,Math.ceil((deadline-performance.now())/1000));$('#gameTime').textContent=left+'s';if(left===0)finish('Time is up.')}
let bubbleId=0;function addBubble(){if(!running||mode!=='bubbles')return;const arena=$('#bubbleArena'),size=36+Math.random()*35,b=document.createElement('button');bubbleId++;b.className='bubble';b.setAttribute('aria-label','Pop bubble '+bubbleId);b.style.width=b.style.height=size+'px';b.style.left=Math.random()*Math.max(1,arena.clientWidth-size-12)+6+'px';b.style.top=Math.random()*(arena.clientHeight-size-12)+6+'px';b.textContent='✧';b.onclick=()=>{if(!running)return;score++;updateScore();b.remove();addBubble()};arena.append(b)}
const canvas=$('#dinoCanvas'),ctx=canvas.getContext('2d');let y=0,velocity=0,obstacles=[],spawnAt=0,last=0,distance=0;function drawDino(){const w=canvas.clientWidth,dpr=devicePixelRatio||1;if(canvas.width!==w*dpr||canvas.height!==250*dpr){canvas.width=w*dpr;canvas.height=250*dpr}ctx.setTransform(dpr,0,0,dpr,0,0);const style=getComputedStyle(document.documentElement),ink=style.getPropertyValue('--ink').trim(),accent=style.getPropertyValue('--accent').trim(),line=style.getPropertyValue('--line').trim();ctx.clearRect(0,0,w,250);ctx.strokeStyle=line;ctx.beginPath();ctx.moveTo(0,202);ctx.lineTo(w,202);ctx.stroke();ctx.fillStyle=accent;const x=47,top=164-y;ctx.fillRect(x,top+10,25,25);ctx.fillRect(x+15,top,25,21);ctx.fillRect(x-9,top+19,15,9);ctx.fillRect(x+4,top+35,7,8);ctx.fillRect(x+18,top+35,7,8);ctx.fillStyle=style.getPropertyValue('--bg').trim();ctx.fillRect(x+30,top+5,4,4);ctx.fillStyle=ink;for(const o of obstacles){ctx.fillRect(o.x,202-o.h,14,o.h);ctx.fillRect(o.x-6,202-o.h+10,6,7);ctx.fillRect(o.x+14,202-o.h+6,6,7)}if(!running){ctx.fillStyle=ink;ctx.font='14px Manrope,system-ui';ctx.textAlign='center';ctx.fillText('A tiny adventure. Press Start.',w/2,80);ctx.textAlign='left'}}
function tick(time){if(!running)return;const dt=Math.min(.035,(time-last)/1000||.016);last=time;velocity+=1100*dt;y=Math.max(0,y-velocity*dt);if(y===0)velocity=0;distance+=dt*100;score=Math.floor(distance/10);updateScore();spawnAt-=dt;if(spawnAt<=0){obstacles.push({x:canvas.clientWidth+25,h:25+Math.random()*18});spawnAt=1.1+Math.random()*.65}for(const o of obstacles)o.x-=(230+distance/12)*dt;obstacles=obstacles.filter(o=>o.x>-25);drawDino();if(obstacles.some(o=>o.x<86&&o.x+14>48&&202-o.h<207-y)){finish('The cactus won this round.');drawDino();return}frame=requestAnimationFrame(tick)}function jump(){if(running&&mode==='dino'&&y===0)velocity=-480}
$('#gameStart').onclick=()=>{stop();running=true;score=0;updateScore();deadline=performance.now()+20000;$('#gameStart').textContent='Restart';$('#gameStatus').textContent=mode==='bubbles'?'Pop as many bubbles as you can in 20 seconds.':'Tap Jump or press Space / ↑ to clear the cacti.';clock();interval=setInterval(clock,200);if(mode==='bubbles'){$('#bubbleIdle').hidden=true;$('#bubbleArena').querySelectorAll('.bubble').forEach(b=>b.remove());for(let i=0;i<9;i++)addBubble()}else{y=0;velocity=0;obstacles=[];spawnAt=.9;distance=0;last=performance.now();frame=requestAnimationFrame(tick)}};$('#gameJump').onclick=jump;canvas.onclick=jump;canvas.onkeydown=e=>{if(['Space','ArrowUp'].includes(e.code)){e.preventDefault();jump()}};document.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{stop();mode=b.dataset.game;document.querySelectorAll('[data-game]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});$('#bubbleArena').hidden=mode!=='bubbles';canvas.hidden=mode!=='dino';$('#gameJump').hidden=mode!=='dino';$('#gameStart').textContent='Start';score=0;updateScore();$('#gameTime').textContent='20s';$('#gameStatus').textContent=mode==='bubbles'?'A 20-second break. No account, just a few bubbles.':'Tap Jump or focus the canvas and use Space / ↑.';$('#bubbleIdle').hidden=false;$('#bubbleArena').querySelectorAll('.bubble').forEach(x=>x.remove());$('#bubbleIdle').innerHTML='<div><strong>A little pop of joy.</strong>Press Start, then tap the bubbles.</div>';readBest();if(mode==='dino'){y=0;obstacles=[];drawDino()}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&running)finish('Round ended while the page was away.')});window.addEventListener('resize',()=>{if(mode==='dino'&&!running)drawDino()});const observer=new MutationObserver(()=>{if(mode==='dino'&&!running)drawDino()});observer.observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});readBest();drawDino()}
